import org.eclipse.swt.widgets.Table;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.swt.SWT;
import org.eclipse.swt.graphics.Rectangle;

public class Example {
    void foo(int width, int height) {
        Shell shell = new Shell();
        Table table = new Table(shell, SWT.NONE);
        Rectangle area = new Rectangle(0, 0, width, height);
        table.setSize(area.width, area.height); // Should match
    }

    void bar(int width, int height) {
        Shell shell = new Shell();
        Table table = new Table(shell, SWT.NONE);
        table.setSize(width, height); // Should match
    }
}

afterExample:
import org.eclipse.swt.widgets.Table;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.swt.SWT;
import org.eclipse.swt.graphics.Rectangle;

public class Example {
    void foo(int width, int height) {
        Shell shell = new Shell();
        Table table = new Table(shell, SWT.NONE);
        Rectangle area = new Rectangle(0, 0, width, height);
        table.setBounds(0, 0, area.width, area.height); // Replaced
    }

    void bar(int width, int height) {
        Shell shell = new Shell();
        Table table = new Table(shell, SWT.NONE);
        table.setBounds(0, 0, width, height); // Replaced
    }
}

